package com.crm.fees.service;
import com.crm.fees.dto.FeeCycleContracts.*;import com.crm.fees.entity.*;import com.crm.fees.repository.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;
@Service @Transactional public class FeeCycleService {
 private final FeeOfferingRepository offerings;private final FeeTariffRepository tariffs;private final FeeTimeRepository times;private final FeeRepository fees;private final FeeReferenceDirectory directory;
 @jakarta.persistence.PersistenceContext private jakarta.persistence.EntityManager em;
 public FeeCycleService(FeeOfferingRepository o,FeeTariffRepository t,FeeTimeRepository e,FeeRepository f,FeeReferenceDirectory d){offerings=o;tariffs=t;times=e;fees=f;directory=d;}
 private PageRequest page(int page){if(page<0)throw new IllegalArgumentException("Invalid page");return PageRequest.of(page,20,Sort.by("id").descending());}
 @Transactional(readOnly=true) public Page<OfferingView> offerings(String keyword,int page){FeeAuthorization.admin();if(keyword!=null&&keyword.length()>200)throw new IllegalArgumentException("Search too long");return offerings.findByTitleContainingIgnoreCase(keyword==null?"":keyword.trim(),page(page)).map(this::view);}
 public OfferingView createOffering(OfferingInput input,String bearer){FeeAuthorization.admin();FeeFinance.validate(input);directory.validate(input.employeeId(),input.customerId(),bearer);var o=new FeeOffering();o.setTitle(input.title().trim());o.setEmployeeId(input.employeeId());o.setCustomerId(input.customerId());o.setCurrency(input.currency());return view(offerings.saveAndFlush(o));}
 public OfferingView offeringActive(long id,boolean active){FeeAuthorization.admin();var o=lock(id);o.setActive(active);return view(o);}
 @Transactional(readOnly=true) public Page<TariffView> tariffs(long offering,Boolean active,int page){FeeAuthorization.admin();get(offering);var result=tariffs.list(offering,active,page(page));var ids=result.getContent().stream().map(FeeTariff::getId).toList();var used=ids.isEmpty()?Set.<Long>of():new HashSet<>(times.usedTariffs(ids));return result.map(t->view(t,used.contains(t.getId())));}
 public TariffView createTariff(long offering,TariffInput input){FeeAuthorization.admin();FeeFinance.validate(input);var o=lock(offering);active(o);range(input);overlap(offering,0L,input);var t=new FeeTariff();t.setOfferingId(offering);apply(t,input);return view(tariffs.saveAndFlush(t),false);}
 public TariffView updateTariff(long id,TariffInput input){FeeAuthorization.admin();FeeFinance.validate(input);var t=tariff(id);var o=lock(t.getOfferingId());refresh(t);active(o);if(times.existsByTariffId(id))throw FeeFinance.conflict();range(input);overlap(o.getId(),id,input);apply(t,input);return view(t,false);}
 public TariffView tariffActive(long id,boolean active){FeeAuthorization.admin();var t=tariff(id);var o=lock(t.getOfferingId());refresh(t);if(active){active(o);overlap(o.getId(),id,new TariffInput(t.getRate(),t.getValidFrom(),t.getValidTo(),true));}t.setActive(active);return view(t,times.existsByTariffId(id));}
 @Transactional(readOnly=true) public Page<TimeView> times(long offering,LocalDate from,LocalDate to,int page){FeeAuthorization.admin();period(from,to);var o=get(offering);return times.findByOfferingIdAndWorkDateBetween(offering,from,to,page(page)).map(t->view(t,o));}
 public TimeView createTime(long offering,NewTime input,String bearer){long actor=FeeAuthorization.admin();FeeFinance.validate(input);uuid(input.requestId());var o=lock(offering);var old=times.findByRequestId(input.requestId());if(old.isPresent()){var t=old.get();if(!Objects.equals(t.getOfferingId(),offering)||!same(t,input.value()))throw FeeFinance.conflict();return view(t,o);}active(o);directory.validate(o.getEmployeeId(),o.getCustomerId(),bearer);var t=new FeeTimeEntry();t.setOfferingId(offering);t.setRequestId(input.requestId());t.setCreatedBy(actor);t.setUpdatedBy(actor);calculate(t,o,input.value());return view(times.saveAndFlush(t),o);}
 public TimeView updateTime(long id,TimeInput input,String bearer){long actor=FeeAuthorization.admin();FeeFinance.validate(input);var t=time(id);var o=lock(t.getOfferingId());refresh(t);editable(t);active(o);if(!t.getWorkDate().equals(input.workDate())||t.getHours().compareTo(input.hours())!=0){directory.validate(o.getEmployeeId(),o.getCustomerId(),bearer);calculate(t,o,input);}else{duplicate(t,input);t.setDescription(input.description().trim());}t.setUpdatedBy(actor);return view(t,o);}
 public TimeView cancelTime(long id,String reason){long actor=FeeAuthorization.admin();FeeFinance.validate(new Cancellation(reason));var t=time(id);var o=lock(t.getOfferingId());refresh(t);editable(t);t.setCancelled(true);t.setCancelReason(reason.trim());t.setActiveSignature(null);t.setUpdatedBy(actor);return view(t,o);}
 public Fee post(long id,String bearer){long actor=FeeAuthorization.admin();var t=time(id);var o=lock(t.getOfferingId());refresh(t);if(t.getFeeId()!=null)return fees.findById(t.getFeeId()).orElseThrow(()->FeeFinance.conflict());editable(t);active(o);directory.validate(o.getEmployeeId(),o.getCustomerId(),bearer);
  var fee=new Fee();fee.setEmployeeId(o.getEmployeeId());fee.setCustomerId(o.getCustomerId());fee.setServiceName(o.getTitle());fee.setDescription(t.getDescription());fee.setWorkDate(t.getWorkDate());fee.setHourlyRate(t.getAppliedRate());fee.setWorkedHours(t.getHours().doubleValue());fee.setExactHours(t.getHours());fee.setAmount(t.getAmount());fee.setCurrency(o.getCurrency());fee.setOfferingId(o.getId());fee.setSourceTimeId(t.getId());fee=fees.saveAndFlush(fee);t.setFeeId(fee.getId());t.setUpdatedBy(actor);return fee;
 }
 private void calculate(FeeTimeEntry t,FeeOffering o,TimeInput input){FeeFinance.validate(input);date(input.workDate());var available=tariffs.applicable(o.getId(),input.workDate(),PageRequest.of(0,2));if(available.size()!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Exactly one active tariff valid on the work date is required");var rate=available.getFirst();BigDecimal amount=FeeFinance.amount(rate.getRate(),input.hours());duplicate(t,input);t.setWorkDate(input.workDate());t.setHours(input.hours());t.setDescription(input.description().trim());t.setTariffId(rate.getId());t.setAppliedRate(rate.getRate());t.setAmount(amount);}
 private void duplicate(FeeTimeEntry t,TimeInput input){String value=t.getOfferingId()+"|"+input.workDate()+"|"+input.hours().stripTrailingZeros().toPlainString()+"|"+input.description().trim().replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);String signature;try{signature=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}if(times.existsByActiveSignatureAndIdNot(signature,t.getId()==null?0L:t.getId()))throw FeeFinance.conflict();t.setActiveSignature(signature);}
 private boolean same(FeeTimeEntry t,TimeInput v){return t.getWorkDate().equals(v.workDate())&&t.getHours().compareTo(v.hours())==0&&t.getDescription().equals(v.description().trim());}
 private void uuid(String s){try{if(!UUID.fromString(s).toString().equals(s))throw new IllegalArgumentException();}catch(RuntimeException e){throw new IllegalArgumentException("Canonical UUID required");}}
 private void editable(FeeTimeEntry t){if(t.isCancelled()||t.getFeeId()!=null)throw FeeFinance.conflict();}
 private void active(FeeOffering o){if(!o.isActive())throw FeeFinance.conflict();}
 private FeeOffering get(long id){return offerings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Offering unavailable"));}
 private FeeOffering lock(long id){var o=offerings.lock(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Offering unavailable"));refresh(o);return o;}
 private void refresh(Object row){if(em!=null)em.refresh(row,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);}
 private FeeTariff tariff(long id){return tariffs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tariff unavailable"));}
 private FeeTimeEntry time(long id){return times.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Time entry unavailable"));}
 private void range(TariffInput i){date(i.validFrom());if(i.validTo()!=null)date(i.validTo());if(i.validTo()!=null&&i.validTo().isBefore(i.validFrom()))throw new IllegalArgumentException("Invalid inclusive tariff period");}
 private void overlap(long offering,long exclude,TariffInput input){if(Boolean.TRUE.equals(input.active())&&tariffs.overlaps(offering,exclude,input.validFrom(),input.validTo()==null?LocalDate.of(9999,12,31):input.validTo())>0)throw FeeFinance.conflict();}
 private void apply(FeeTariff t,TariffInput i){t.setRate(i.rate());t.setValidFrom(i.validFrom());t.setValidTo(i.validTo());t.setActive(i.active());}
 public static void period(LocalDate from,LocalDate to){date(from);date(to);if(to.isBefore(from)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>365)throw new IllegalArgumentException("Choose at most 366 inclusive calendar days");}
 public static void date(LocalDate date){if(date==null||date.getYear()<1000||date.getYear()>9999)throw new IllegalArgumentException("Date outside MySQL DATE range");}
 private OfferingView view(FeeOffering o){return new OfferingView(o.getId().toString(),o.getTitle(),o.getEmployeeId(),o.getCustomerId(),o.getCurrency(),o.isActive());}
 private TariffView view(FeeTariff t,boolean used){return new TariffView(t.getId().toString(),t.getOfferingId().toString(),t.getRate(),t.getValidFrom(),t.getValidTo(),t.isActive(),used);}
 private TimeView view(FeeTimeEntry t,FeeOffering o){return new TimeView(t.getId().toString(),o.getId().toString(),t.getWorkDate(),t.getHours(),t.getDescription(),t.getTariffId().toString(),t.getAppliedRate(),t.getAmount(),o.getCurrency(),t.getFeeId()==null?null:t.getFeeId().toString(),t.isCancelled(),t.getCancelReason(),t.getCreatedBy().toString(),t.getCreatedAt());}
}